      def self.load(file, follow_inodes, existing_targets, logger:)
        pf = new(file, follow_inodes, logger: logger)
        pf.load(existing_targets)
        pf
      end

      def initialize(file, follow_inodes, logger: nil)
        @file = file
        @logger = logger
        @file_mutex = Mutex.new
        @map = {}
        @follow_inodes = follow_inodes
      end

      def [](target_info)
        key = TailInput.position_map_key(target_info, @follow_inodes)
        if m = @map[key]
          return m
        end

        @file_mutex.synchronize {
          @file.seek(0, IO::SEEK_END)
          seek = TailInput.seek_after_path_field(@file.pos, target_info.path, nil)
          @file.write "#{target_info.path}\t" + TailInput.format_position_inode_pair(0, 0) + "\n"
          @map[key] = FilePositionEntry.new(@file, @file_mutex, seek, 0, 0)
        }
      end

      def unwatch(target_info)
        if (entry = @map.delete(TailInput.position_map_key(target_info, @follow_inodes)))
          entry.update_pos(UNWATCHED_POSITION)
        end
      end

      def load(existing_targets = nil)
        compact(existing_targets)

        map = {}
        @file_mutex.synchronize do
          @file.pos = 0

          @file.each_line do |line|
            parsed = TailInput.parse_position_file_line(line)
            next if parsed.nil?

            path, pos, ino = parsed
            seek = @file.pos - line.bytesize + path.bytesize + 1
            key_info = TargetInfo.new(path, ino)
            map[TailInput.position_map_key(key_info, @follow_inodes)] = FilePositionEntry.new(@file, @file_mutex, seek, pos, ino)
          end
        end

        @map = map
      end

