          @file.truncate(0)
          @file.write(entries.join)
        end
      end

      def fetch_compacted_entries(existing_targets = nil)
        entries = {}

        @file.pos = 0
        file_pos = 0
        @file.each_line do |line|
          parsed = TailInput.parse_position_file_line(line)
          if parsed.nil?
            @logger.warn "Unparsable line in pos_file: #{line}" if @logger
            next
          end

